'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var rempio2 = require( '@stdlib/math/base/special/rempio2' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var absf = require( '@stdlib/math/base/special/absf' );
var EPS = require( '@stdlib/constants/float32/eps' );
var kernelSinf = require( './../lib' );


// FIXTURES //

var smallRange = require( './fixtures/julia/small_range.json' );
var largePositive = require( './fixtures/julia/large_positive.json' );
var largeNegative = require( './fixtures/julia/large_negative.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof kernelSinf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN` for either parameter', function test( t ) {
	var v = kernelSinf( NaN, 0.0 );
	t.equal( isnanf( v ), true, 'returns expected value' );

	v = kernelSinf( 4.0, NaN );
	t.equal( isnanf( v ), true, 'returns expected value' );

	v = kernelSinf( NaN, NaN );
	t.equal( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function evaluates the sine for input values on the interval `[-pi/4, pi/4]`', function test( t ) {
	var expected;
	var values;
	var delta;
	var tol;
	var out;
	var x;
	var i;

	values = smallRange.x;
	expected = smallRange.expected;
	for ( i = 0; i < values.length; i++ ) {
		x = float64ToFloat32(values[ i ]);
		out = kernelSinf( x, 0.0 );
		expected[ i ] = float64ToFloat32( expected[ i ] );

		if( out === expected[i] ) {
			t.strictEqual( out, expected[i], 'returns explected value' );
		}
		else {
			delta = absf( out - expected[ i ] );
			tol = EPS * absf(expected[ i ]);

			t.ok( delta <= tol, 'within tolerance. x: ' + x + '. out: ' + out + '. expected: ' + expected[i] + '. delta: ' + delta + '. tol: ' + tol + '.' );
		}
	}
	t.end();
});

tape( 'the function can be used to compute the sine for input values outside of `[-pi/4, pi/4]` after argument reduction via `rempio2` (positive)', function test( t ) {
	var expected;
	var values;
	var delta;
	var tol;
	var out;
	var x;
	var y;
	var n;
	var i;

	values = largePositive.x;
	expected = largePositive.expected;
	y = [ 0.0, 0.0 ];
	for ( i = 0; i < values.length; i++ ) {
		x = float64ToFloat32(values[ i ]);
		n = rempio2( x, y );

		y[0] = float64ToFloat32(y[0]);
		y[1] = float64ToFloat32(y[1]);

		expected[i] = float64ToFloat32(expected[i]);

		switch ( n & 3 ) {
		case 0:
			out = kernelSinf( y[ 0 ], y[ 1 ] );

			if ( out === expected[i] ) {
				t.strictEqual( out, expected[i], 'returns expected value' );
			}
			else {
				delta = absf(out - expected[i]);
				tol = EPS * absf(expected[i]);

				t.ok( delta <= tol, 'within tolerance. x: ' + x + '. out: ' + out + '. expected: ' + expected[i] + '. delta: ' + delta + '. tol: ' + tol + '.' );
			}
			break;
		case 2:
			out = -kernelSinf( y[ 0 ], y[ 1 ] );
			out = float64ToFloat32(out);  // Ensure single precision

			if ( out === expected[i] ) {
				t.strictEqual( out, expected[i], 'returns expected value' );
			}
			else {
				delta = absf(out - expected[i]);
				tol = EPS * absf(expected[i]);

				t.ok( delta <= tol, 'within tolerance. x: ' + x + '. out: ' + out + '. expected: ' + expected[i] + '. delta: ' + delta + '. tol: ' + tol + '.' );
			}
			break;
		default:
			break;
		}
	}
	t.end();
});

